// Physics, placement and objective state
const floorObject=scene.getObjectByName('floor'),platformObject=scene.getObjectByName('relay platform'),pedestalObject=scene.getObjectByName('pedestal');
for(const o of [floorObject,platformObject,pedestalObject]){const n=colliders.indexOf(o);if(n>=0)colliders.splice(n,1)}
const player={pos:new THREE.Vector3(-4,1.65,10),vel:new THREE.Vector3(),yaw:0,pitch:0,onGround:true};camera.position.copy(player.pos);
const raycaster=new THREE.Raycaster(),keys={},clock=new THREE.Clock();let active=false,hasCore=false,completed=false,lastPortalSide=0,toastTimer=0,touchLook=null;
const toastEl=document.querySelector('#toast'),promptEl=document.querySelector('#prompt'),statusText=document.querySelector('#statusText'),portalStatus=document.querySelector('#portalStatus'),objectiveText=document.querySelector('#objectiveText');
function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');toastTimer=2.2}
function setPortal(hit){const normal=hit.object.userData.mountNormal.clone().normalize();portalNormal.copy(normal);portalPosition.copy(hit.point).addScaledVector(normal,.075);if(Math.abs(normal.x)>.5){portalPosition.x=-11.57;portalPosition.y=THREE.MathUtils.clamp(hit.point.y,1.55,6.05);portalPosition.z=THREE.MathUtils.clamp(hit.point.z,-12.7,12.7)}else{portalPosition.z=-14.57;portalPosition.y=THREE.MathUtils.clamp(hit.point.y,1.55,6.05);portalPosition.x=THREE.MathUtils.clamp(hit.point.x,-10.7,10.7)}portalQuaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),normal);portalGroup.position.copy(portalPosition);portalGroup.quaternion.copy(portalQuaternion);portalGroup.visible=true;portalPlaced=true;lastPortalSide=player.pos.clone().sub(portalPosition).dot(portalNormal);statusText.textContent='ONE PORTAL: ACTIVE';portalStatus.classList.add('live');toast('SINGLE PORTAL LINKED · RELAY SIGNAL STABLE')}
function aimPlace(){raycaster.setFromCamera(new THREE.Vector2(0,0),camera);const hit=raycaster.intersectObjects(portalSurfaces,false)[0];if(hit&&hit.distance<22){setPortal(hit)}else toast('AIM AT A MARKED PORTAL SURFACE')}
function jump(){if(player.onGround){player.vel.y=6.1;player.onGround=false}}
function inputLook(dx,dy){player.yaw-=dx*.0023;player.pitch-=dy*.0021;player.pitch=THREE.MathUtils.clamp(player.pitch,-1.25,1.25);camera.rotation.set(player.pitch,player.yaw,0)}
function surfaceAt(x,z,fromFeet){let y=0;if(x>.5&&x<11.5&&z>-12&&z<-2)y=1.325;if(x>7.38&&x<9.42&&z>-8&&z<-6)y=2.45;return y}
function blocked(x,z,feet){const radius=.32,head=feet+1.6;for(const m of colliders){const b=new THREE.Box3().setFromObject(m);if(head<=b.min.y+.02||feet>=b.max.y-.02)continue;if(x+radius>b.min.x&&x-radius<b.max.x&&z+radius>b.min.z&&z-radius<b.max.z)return true}return false}
function update(dt){if(!active)return;dt=Math.min(dt,.035);camera.rotation.set(player.pitch,player.yaw,0);const speed=keys.ShiftLeft?5.4:4.15;let forward=(keys.KeyW?1:0)-(keys.KeyS?1:0),side=(keys.KeyD?1:0)-(keys.KeyA?1:0);if(touchMove){forward+=touchMove.y;side+=touchMove.x}const len=Math.hypot(forward,side)||1;forward/=len;side/=len;const dx=(Math.sin(player.yaw)*forward+Math.cos(player.yaw)*side)*speed*dt;const dz=(-Math.cos(player.yaw)*forward+Math.sin(player.yaw)*side)*speed*dt;let feet=player.pos.y-1.65;
if(!blocked(player.pos.x+dx,player.pos.z,feet))player.pos.x+=dx;if(!blocked(player.pos.x,player.pos.z+dz,feet))player.pos.z+=dz;
const oldFeet=feet;player.vel.y-=15.5*dt;player.pos.y+=player.vel.y*dt;feet=player.pos.y-1.65;const ground=surfaceAt(player.pos.x,player.pos.z,feet);if(player.vel.y<=0&&oldFeet>=ground-.12&&feet<=ground){player.pos.y=ground+1.65;player.vel.y=0;player.onGround=true}else player.onGround=false;
// One placed aperture links to a fixed relay beacon. Crossing the plane consumes no portal or ammo.
if(portalPlaced){const sideNow=player.pos.clone().sub(portalPosition).dot(portalNormal);if(lastPortalSide>.04&&sideNow<=.04&&Math.abs(player.pos.y-portalPosition.y)<1.55&&Math.abs(player.pos.clone().sub(portalPosition).dot(new THREE.Vector3().crossVectors(portalNormal,new THREE.Vector3(0,1,0))))<1.05){player.pos.set(2.4,2.975,-7.2);player.vel.set(0,0,0);player.yaw=Math.PI/2;player.pitch=0;camera.rotation.set(0,player.yaw,0);toast('RELAY TRANSIT COMPLETE · YOU ARE ON THE FAR SIDE');}lastPortalSide=player.pos.clone().sub(portalPosition).dot(portalNormal)}
if(!hasCore&&Math.hypot(player.pos.x-8.4,player.pos.z+7)<1.4&&player.pos.y>3.1){hasCore=true;coreGroup.visible=false;objectiveText.textContent='Core acquired. Reach the illuminated exit door.';doorLamp.material=cyanMat;const d=colliders.indexOf(exitDoor);if(d>=0)colliders.splice(d,1);exitDoor.material=cyanMat;toast('ENERGY CORE ACQUIRED · EXIT UNLOCKED')}
if(hasCore&&Math.hypot(player.pos.x-10.7,player.pos.z-5.6)<1.15){completed=true;active=false;document.querySelector('#win').style.display='grid';if(document.pointerLockElement)document.exitPointerLock()}
// contextual prompt
if(!portalPlaced){promptEl.textContent='AIM AT A MARKED SURFACE  ·  CLICK TO PLACE YOUR ONE PORTAL';promptEl.style.display='block'}else if(Math.hypot(player.pos.x-2.4,player.pos.z+7.2)<2.4&&!hasCore){promptEl.textContent='RELAY PAD ACTIVE  ·  STEP TO THE CORE PEDESTAL';promptEl.style.display='block'}else if(hasCore&&Math.hypot(player.pos.x-10.7,player.pos.z-5.6)<4){promptEl.textContent='EXIT UNLOCKED  ·  WALK THROUGH';promptEl.style.display='block'}else promptEl.style.display='none';
player.pos.x=THREE.MathUtils.clamp(player.pos.x,-11.2,11.2);player.pos.z=THREE.MathUtils.clamp(player.pos.z,-14.1,14.1);camera.position.copy(player.pos);
}
function animate(t){requestAnimationFrame(animate);const dt=clock.getDelta();update(dt);drawPortal(t);rings.forEach((r,i)=>{r.rotation.z=t*.00045*(i%2?-.7:1);r.scale.setScalar(1+Math.sin(t*.002+i)*.04)});if(coreGroup.visible){coreGroup.rotation.y=t*.0007;coreGroup.position.y=3.15+Math.sin(t*.002)*.09}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)toastEl.classList.remove('show')}renderer.render(scene,camera)}requestAnimationFrame(animate);
// Desktop pointer lock and keyboard; touch uses a virtual stick plus drag-to-look.
const canvas=renderer.domElement;document.querySelector('#startBtn').addEventListener('click',()=>{document.querySelector('#intro').style.display='none';document.querySelector('#hud').style.display='block';active=true;if(innerWidth>700)canvas.requestPointerLock?.();toast('TEST STARTED · FIND A MARKED PORTAL SURFACE')});
document.querySelector('#againBtn').addEventListener('click',()=>location.reload());document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement===canvas)active=true});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas)inputLook(e.movementX,e.movementY)});
canvas.addEventListener('click',e=>{if(!active)return;if(innerWidth>700&&document.pointerLockElement!==canvas){canvas.requestPointerLock?.();return}aimPlace()});document.addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='Space'){e.preventDefault();jump()}if(e.code==='KeyR'&&portalPlaced)toast('PORTAL RETAINED · CLICK A NEW MARKED SURFACE TO REPOSITION')});document.addEventListener('keyup',e=>keys[e.code]=false);document.addEventListener('contextmenu',e=>e.preventDefault());
// Mobile: look by dragging the world; joystick controls movement.
canvas.addEventListener('touchstart',e=>{if(innerWidth<=700&&active){const t=e.changedTouches[0];touchLook={x:t.clientX,y:t.clientY}}},{passive:true});canvas.addEventListener('touchmove',e=>{if(!touchLook)return;const t=e.changedTouches[0];inputLook(t.clientX-touchLook.x,t.clientY-touchLook.y);touchLook={x:t.clientX,y:t.clientY}},{passive:true});canvas.addEventListener('touchend',()=>touchLook=null,{passive:true});
let touchMove=null;const stick=document.querySelector('#stick'),nub=document.querySelector('#nub');stick.addEventListener('pointerdown',e=>{stick.setPointerCapture(e.pointerId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.buttons)moveStick(e)});stick.addEventListener('pointerup',()=>{touchMove=null;nub.style.transform='translate(-50%,-50%)'});function moveStick(e){const r=stick.getBoundingClientRect(),x=e.clientX-(r.left+r.width/2),y=e.clientY-(r.top+r.height/2),d=Math.hypot(x,y),m=Math.min(d,42),a=Math.atan2(y,x),nx=Math.cos(a)*m,ny=Math.sin(a)*m;nub.style.transform=`translate(calc(-50% + ${nx}px),calc(-50% + ${ny}px))`;touchMove={x:nx/42,y:-ny/42}}
document.querySelector('#placeBtn').addEventListener('click',()=>aimPlace());document.querySelector('#jumpBtn').addEventListener('pointerdown',jump);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
</script></body></html>

